package com.zad.almoslem;
import android.app.Activity;import android.content.Intent;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.os.Bundle;import android.view.Gravity;import android.widget.*;
public class MoreActivity extends Activity{
int dp(float n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}void open(Class<?> c){startActivity(new Intent(this,c));}
TextView label(String s,int z,int c,boolean b){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);t.setGravity(Gravity.RIGHT);if(b)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}
void add(LinearLayout root,String title,String desc,Class<?> target){LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(15),dp(12),dp(15),dp(12));GradientDrawable bg=new GradientDrawable();bg.setColor(Color.WHITE);bg.setCornerRadius(dp(15));card.setBackground(bg);card.addView(label(title,17,Color.rgb(8,48,40),true));TextView d=label(desc,12,Color.DKGRAY,false);d.setPadding(0,dp(4),0,0);card.addView(d);card.setOnClickListener(v->open(target));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(10);root.addView(card,lp);}
@Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.rgb(8,48,40));getWindow().setNavigationBarColor(Color.rgb(8,48,40));build();}
void build(){ScrollView scroll=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(14),dp(16),dp(14),dp(24));root.setBackgroundColor(Color.rgb(244,247,243));scroll.addView(root);TextView title=label("المزيد من خدمات زاد المسلم",23,Color.rgb(8,48,40),true);title.setGravity(Gravity.CENTER);title.setPadding(0,0,0,dp(14));root.addView(title);
add(root,"🕌 مواقيت الصلاة","عرض المواقيت وإعدادات الصلاة",PrayerDashboardActivity.class);add(root,"⚙️ إعدادات الأذان والصوت","التحكم في الأذان والتنزيلات ومستوى الصوت",MainActivity.class);add(root,"📻 إذاعات القرآن الكريم","إذاعة القاهرة والسعودية وفلسطين",RadioActivity.class);add(root,"🎧 الرقية الشرعية والابتهالات","تسجيلات الرقية بأصوات عدد من المشايخ",AudioLibraryActivity.class);add(root,"🧭 بوصلة القبلة","تحديد اتجاه القبلة",QiblaActivity.class);add(root,"📚 مكتبة خطب الجمعة","الخطب والموضوعات الدعوية",KhutbahLibraryActivity.class);add(root,"📖 المكتبة الإسلامية","الكتب والسنة والأدعية",FaithLibraryActivity.class);add(root,"🗓️ التقويم الهجري والميلادي","مواعيد ومناسبات",CalendarActivity.class);add(root,"🧒 ركن الأطفال","محتوى إيماني للصغار",KidsCornerActivity.class);add(root,"☀️ وردي اليومي","متابعة الورد والأذكار",DailyWirdActivity.class);add(root,"🌙 ورد يوم الجمعة","أذكار وأعمال يوم الجمعة",FridayWirdActivity.class);add(root,"⏰ التنبيهات اليومية","إدارة التذكيرات",DailyReminderSettingsActivity.class);add(root,"🌐 اللغة","اختيار لغة واجهة التطبيق",LanguageSettingsActivity.class);setContentView(AppTabs.wrap(this,scroll,"more"));}
}